CREATE DATABASE IF NOT EXISTS `pasarin_db` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `pasarin_db`;

-- 1. TABEL BANNERS
CREATE TABLE IF NOT EXISTS `banners` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `config_json` LONGTEXT NOT NULL,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO `banners` (`id`, `config_json`) VALUES ('main_banner', '{"left":{"badge":"✨ PASARIN PILIH LOKAL","title":"Kreasi Unggulan & Inovasi Nusantara","subtitle":"Karya Terbaik Anak Bangsa","pills":["🏷️ Produk Unik Asli Indonesia","⚡ Inovasi Lokal Rasa Global","⭐ Kualitas Unggulan Nusantara"],"modelImage":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=320&auto=format&fit=crop&q=80","bgGradient":"linear-gradient(135deg, #1d3f0d 0%, #285715 100%)","targetUrl":"#/search?category=Pilih+Lokal"},"right":{"title":"Spesial Diskon & Voucher","modelImage1":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=240&auto=format&fit=crop&q=80","modelImage2":"https://images.unsplash.com/photo-1517841905240-472988babdf9?w=240&auto=format&fit=crop&q=80","pill1Title":"DISKON S.D.","pill1Val":"80%","pill2Title":"VOUCHER","pill2Val":"100RB","bgGradient":"linear-gradient(135deg, #3b0764 0%, #581c87 50%, #4c1d95 100%)","targetUrl":"#/search?q=promo"}}') ON DUPLICATE KEY UPDATE `config_json`=VALUES(`config_json`);

-- 2. TABEL USERS (AKUN ADMIN & AKUN PEMBELI)
CREATE TABLE IF NOT EXISTS `users` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `name` VARCHAR(150) NOT NULL,
  `email` VARCHAR(150) NOT NULL UNIQUE,
  `phone` VARCHAR(50) DEFAULT NULL,
  `role` VARCHAR(50) DEFAULT 'buyer',
  `salt` VARCHAR(255) NOT NULL,
  `hash` VARCHAR(255) NOT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

