-- 3. TABEL PRODUCTS (SELURUH PRODUK LENGKAP DENGAN 168PART SHOPEE)
CREATE TABLE IF NOT EXISTS `products` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `category` VARCHAR(100) NOT NULL,
  `price` DECIMAL(14,2) NOT NULL,
  `original_price` DECIMAL(14,2) DEFAULT NULL,
  `discount_percent` INT DEFAULT 0,
  `rating` DECIMAL(2,1) DEFAULT 5.0,
  `sold_count` INT DEFAULT 0,
  `stock` INT DEFAULT 10,
  `location` VARCHAR(100) DEFAULT 'Indonesia',
  `shop_name` VARCHAR(150) DEFAULT 'Pasarin Partner',
  `shop_type` VARCHAR(50) DEFAULT 'Star',
  `icon` VARCHAR(50) DEFAULT 'bag',
  `image` TEXT DEFAULT NULL,
  `bg_pattern` VARCHAR(50) DEFAULT '#f8fafc',
  `is_flash_sale` TINYINT(1) DEFAULT 0,
  `flash_sale_sold` INT DEFAULT 0,
  `description` TEXT DEFAULT NULL,
  `specs` JSON DEFAULT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO `products` (`id`, `name`, `slug`, `category`, `price`, `original_price`, `discount_percent`, `rating`, `sold_count`, `stock`, `location`, `shop_name`, `shop_type`, `icon`, `image`, `bg_pattern`, `is_flash_sale`, `flash_sale_sold`, `description`, `specs`) VALUES ('prod-1', 'DJI Osmo Action 4 Standard Combo 4K/120fps', 'dji-osmo-action-4-standard-combo', 'Fotografi', 3940000, 4899000, 20, 4.9, 1420, 45, 'Jakarta Barat', 'DJI Official Store', 'Mall', 'cam', 'https://images.unsplash.com/photo-1526170375885-4d8ecf77b99f?w=500&auto=format&fit=crop&q=80', '#f1f5f9', 1, 85, 'Kamera aksi dengan sensor besar 1/1.3 inci, performa low-light luar biasa, ketahanan air hingga 18 meter tanpa case, dan layar sentuh ganda responsif warna penuh.', '["Sensor: 1/1.3 inci CMOS","Video: 4K/120fps & 155° Ultra-Wide FOV","Stabilisasi: RockSteady 3.0+ & HorizonSteady","Tahan Air: 18m tanpa case"]') ON DUPLICATE KEY UPDATE `price`=VALUES(`price`);
